import{Z as s,e as t,f as o,a0 as i}from"./chunks/framework.DmpHOl9T.js";const b=JSON.parse('{"title":"Submissions","description":"","frontmatter":{},"headers":[],"relativePath":"submissions/submissions.md","filePath":"submissions/submissions.md","lastUpdated":null}'),a={name:"submissions/submissions.md"};function n(r,e,l,d,u,m){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="submissions" tabindex="-1">Submissions <a class="header-anchor" href="#submissions" aria-label="Permalink to &quot;Submissions&quot;">​</a></h1><p>Submissions are the saved records created when someone interacts with a Formie form.</p><p>They can represent a completed submission, a partially saved draft, or a submission that has been marked as spam. Once a submission exists, you can review it in the control panel, organise it with statuses, export its data, relate it to other elements, or render it back into the front end for editing.</p><h2 id="submission-states" tabindex="-1">Submission States <a class="header-anchor" href="#submission-states" aria-label="Permalink to &quot;Submission States&quot;">​</a></h2><p>Formie tracks a few built-in submission states:</p><ul><li><strong>complete</strong> submissions have finished the normal submission flow</li><li><strong>incomplete</strong> submissions are partially saved, such as save-and-continue drafts or multi-page progress</li><li><strong>spam</strong> submissions have been screened and marked as spam</li></ul><p>These are system states. They describe what happened during submission processing.</p><p>Custom <a href="/submissions/submission-statuses">Statuses</a> are different. A status is your team&#39;s workflow label on top of the saved submission, such as <code>new</code>, <code>approved</code>, or <code>closed</code>.</p><h2 id="common-ways-to-work-with-submissions" tabindex="-1">Common Ways to Work with Submissions <a class="header-anchor" href="#common-ways-to-work-with-submissions" aria-label="Permalink to &quot;Common Ways to Work with Submissions&quot;">​</a></h2><h3 id="organise-them-with-statuses" tabindex="-1">Organise Them with Statuses <a class="header-anchor" href="#organise-them-with-statuses" aria-label="Permalink to &quot;Organise Them with Statuses&quot;">​</a></h3><p>Use <a href="/submissions/submission-statuses">Statuses</a> when your team needs labels for review, follow-up, or internal processing after a submission has been saved.</p><h3 id="export-submission-data" tabindex="-1">Export Submission Data <a class="header-anchor" href="#export-submission-data" aria-label="Permalink to &quot;Export Submission Data&quot;">​</a></h3><p>Use <a href="/reports/reports">Reports</a> when you need saved filters, summary counts, charts, on-demand export, or <a href="/reports/scheduled-reports">scheduled email delivery</a>.</p><p>For a one-off file without saving a report definition, run a report and choose an export format from the report run screen.</p><h3 id="relate-submissions-to-other-elements" tabindex="-1">Relate Submissions to Other Elements <a class="header-anchor" href="#relate-submissions-to-other-elements" aria-label="Permalink to &quot;Relate Submissions to Other Elements&quot;">​</a></h3><p>Use <a href="/submissions/relations">Relations</a> when a submission belongs to another Craft element such as an entry or product, or when you want to look up related submissions later.</p><h3 id="select-submissions-from-other-elements" tabindex="-1">Select Submissions from Other Elements <a class="header-anchor" href="#select-submissions-from-other-elements" aria-label="Permalink to &quot;Select Submissions from Other Elements&quot;">​</a></h3><p>Use <a href="/submissions/element-field">Element Field</a> when you want another Craft element to choose and store a reference to a Formie submission.</p><h3 id="edit-submissions-in-the-control-panel" tabindex="-1">Edit Submissions in the Control Panel <a class="header-anchor" href="#edit-submissions-in-the-control-panel" aria-label="Permalink to &quot;Edit Submissions in the Control Panel&quot;">​</a></h3><p>When you view or edit a submission in the control panel, Formie can honour the same <a href="/forms/conditions">field and page conditions</a> used on the front end.</p><p>Set the default under <strong>Formie → Settings → Submissions → Control Panel Field Conditions</strong>. Override per form under <strong>Form → Settings → Submissions</strong> — choose <strong>Use Formie default</strong> to inherit the plugin setting.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Behaviour</th></tr></thead><tbody><tr><td><strong>Follow field conditions</strong></td><td>Conditionally hidden fields are omitted. Conditions re-evaluate as you edit; values for hidden fields are cleared on save.</td></tr><tr><td><strong>Follow field conditions (show hidden fields collapsed)</strong></td><td>Same as above, but hidden fields appear collapsed so admins can expand them when needed.</td></tr><tr><td><strong>Show all fields</strong></td><td>Every field is always visible; no live condition evaluation.</td></tr></tbody></table><p>Use <strong>Show all fields</strong> when your team prefers the full layout at all times.</p><p>When a submission is saved in the control panel, Formie records the Craft user who made the edit. Enable the <strong>Last Edited By</strong> column from the submission index column menu to see who last updated each submission.</p><h3 id="let-users-edit-saved-submissions" tabindex="-1">Let Users Edit Saved Submissions <a class="header-anchor" href="#let-users-edit-saved-submissions" aria-label="Permalink to &quot;Let Users Edit Saved Submissions&quot;">​</a></h3><p>If you need to render an existing submission back into the front end so a user can update it, see <a href="/templates/editing-submissions">Editing Submissions</a>.</p><h2 id="developer-access" tabindex="-1">Developer Access <a class="header-anchor" href="#developer-access" aria-label="Permalink to &quot;Developer Access&quot;">​</a></h2><p>If you are working with submissions in templates or custom code:</p><ul><li>use <a href="/getting-elements/submission-queries">Submission Queries</a> to fetch submissions in Twig or PHP</li><li>use <a href="/developers/submission-workflow">Submission Workflow</a> when you need to hook into submission processing stages or tasks</li><li>use <a href="/developers/submission-content">Submission Content</a> when you need the right value format for output, exports, summaries, emails, or integrations</li><li>use <a href="/reference/submission">Submission</a> for the public properties and methods available on the element itself</li></ul>',29)])])}const c=s(a,[["render",n]]);export{b as __pageData,c as default};
